n_ordinal = 26) as actual, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 28) as vendor, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 29) as status, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 30) as flag, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 31) as external_notes, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 32) as internal_notes, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 33) as account_code, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 35) as cost_center, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 36) as urid_dimension, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 37) as tax_type, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 38) as currency, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 39) as created_by, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 40) as created_at, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 41) as updated_at
