  on v.template_code = t.template_code and v.sheet_name = t.sheet_name and v.source_row = t.source_row
where t.template_code = 'XOS-4.0' and t.sheet_name = 'Budget Expenses'
group by t.source_row),
s1 as (select r.*, (coalesce((select sum(x.total_amount) from xpms.v_sheet_po_line_items x where x.expense_ref_id = r.record_id), 0) + coalesce((select sum(x.total_amount) from xpms.v_sheet_change_orders x where x.expense_ref_id = r.record_id and x.status = 'Approved'), 0)) as rate from s0 r),
s2 as (select r.*, (case when r.quantity is null then null else round(xpms.pb_n(r.quantity) * r.rate, 2) end) as estimate from s1 r),
s3 as (select r.*, (r.estimate) as budget from s2 r),
s4 as (select r.*, (coalesce((select sum(x.total_amount) from xpms.v_sheet_po_line_items x where x.expense_ref_id = r.record_id), 0) + coalesce((select sum(x.total_amount) from xpms.v_sheet_change_orders x where x.expense_ref_id = r.record_id and x.status = 'Approved'), 0)) as committed from s3 r),
s5 as (select r.*, (case when r.budget is null and r.committed is null then null else greatest(coalesce(r.budget, 0), coalesce(r.committed, 0)) end) as forecast from s4 r),
s6 as (select r.*, (coalesce(r.budget, 0) - coalesce(xpms.pb_n(r.actual), 0)) as variance from s5 r),
s7 as (select r.*, ((select g.account_name from xpms.dim_gl_account g where g.account_code = r.account_code)) as account_name from s6 r)
select * from s7;
