create view xpms.v_sheet_production_schedule with (security_invoker = true) as
with s0 as (select t.source_row, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 1) as activity_id, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 2) as project_id, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 3) as parent_activity_id, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 4) as wbs_code, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 5) as phase_code, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 6) as phase, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 7) as act, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 8) as gate, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 9) as activity_name, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 10) as activity_type, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 11) as deliverable, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 12) as sop_id, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 13) as owner_role, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 14) as personnel_id, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 15) as start_date, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 16) as end_date, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 17) as duration_days, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 18) as critical_path, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 22) as status, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 23) as flag, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 24) as notes
from xpms.production_template_rows t
left join xpms.production_template_values v
  on v.template_code = t.template_code and v.sheet_name = t.sheet_name and v.source_row = t.source_row
where t.template_code = 'XOS-4.0' and t.sheet_name = 'Production Schedule'
group by t.source_row),
s1 as (select r.*, (case when r.activity_type = 'Milestone Gate' then coalesce((select sum((select count(*) from xpms.v_sheet_production_tasks t where t.activity_id = c.activity_id)) from s0 c where c.parent_activity_id = r.activity_id and c.activity_type = 'Summary Activity'), 0) else (select count(*) from xpms.v_sheet_production_tasks t where t.activity_id = r.activity_id) end) as total_tasks from s0 r),
s2 as (select r.*, (case when r.activity_type = 'Milestone Gate' then coalesce((select sum((select count(*) from xpms.v_sheet_production_tasks t where t.activity_id = c.activity_id and t.status = 'Complete')) from s0 c where c.parent_activity_id = r.activity_id and c.activity_type = 'Summary Activity'), 0) else (select count(*) from xpms.v_sheet_production_tasks t where t.activity_id = r.activity_id and t.status = 'Complete') end) as completed_tasks from s1 r),
s3 as (select r.*, (case when r.total_tasks > 0 then r.completed_tasks::numeric / r.total_tasks when r.status = 'Complete' then 1 else 0 end) as progress_pct from s2 r)
select * from s3;
