create view xpms.v_sheet_work_orders with (security_invoker = true) as
with s0 as (select t.source_row, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 1) as record_id, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 3) as department, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 4) as category, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 5) as sub_category, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 6) as work_order_type, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 7) as priority, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 8) as location_id, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 10) as item_id, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 11) as team_code, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 12) as personnel_id, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 14) as task_title, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 15) as description, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 16) as scope_of_work, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 17) as scheduled_start_date, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 18) as scheduled_end_date, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 19) as actual_start_date, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 20) as actual_end_date, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 21) as estimated_hours, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 22) as actual_hours, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 23) as labor_rate, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 25) as safety_hazard_level, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 26) as completion_percentage, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 27) as status, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 28) as flag, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 29) as resolution_notes, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 30) as notes, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 31) as created_by, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 32) as created_at, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 33) as updated_at
from xpms.production_template_rows t
left join xpms.production_template_values v
  on v.template_code = t.template_code and v.sheet_name = t.sheet_name and v.source_row = t.source_row
where t.template_code = 'XOS-4.0' and t.sheet_name = 'Work Orders'
group by t.source_row),
s1 as (select r.*, (xpms.pb_cover(7, 3)) as project_id from s0 r),
s2 as (select r.*, (case when r.location_id is null then null else (select x.location from xpms.v_sheet_locations x where x.record_id = r.location_id order by x.source_row limit 1) end) as location_name from s1 r),
s3 as (select r.*, (case when r.personnel_id is null then null else nullif(btrim(coalesce((select p.first_name from xpms.v_sheet_personnel_roster p where p.personnel_id = r.personnel_id order by p.source_row limit 1), '') || ' ' || coalesce((select p.last_name from xpms.v_sheet_personnel_roster p where p.personnel_id = r.personnel_id order by p.source_row limit 1), '')), '') end) as lead_assignee_name from s2 r),
s4 as (select r.*, (coalesce(xpms.pb_n(r.actual_hours), 0) * coalesce(xpms.pb_n(r.labor_rate), 0)) as total_labor_cost from s3 r)
select * from s4;
