create view xpms.v_playbook_work_orders with (security_invoker = true) as
select r.source_row::integer as source_row, array[coalesce(r.record_id, ''), xpms.pb_text((r.project_id)::text), coalesce(r.department, ''), coalesce(r.category, ''), coalesce(r.sub_category, ''), coalesce(r.work_order_type, ''), coalesce(r.priority, ''), coalesce(r.location_id, ''), xpms.pb_text((r.location_name)::text), coalesce(r.item_id, ''), coalesce(r.team_code, ''), coalesce(r.personnel_id, ''), xpms.pb_text((r.lead_assignee_name)::text), coalesce(r.task_title, ''), coalesce(r.description, ''), coalesce(r.scope_of_work, ''), coalesce(r.scheduled_start_date, ''), coalesce(r.scheduled_end_date, ''), coalesce(r.actual_start_date, ''), coalesce(r.actual_end_date, ''), coalesce(r.estimated_hours, ''), coalesce(r.actual_hours, ''), coalesce(r.labor_rate, ''), xpms.pb_num((r.total_labor_cost)::numeric), coalesce(r.safety_hazard_level, ''), coalesce(r.completion_percentage, ''), coalesce(r.status, ''), coalesce(r.flag, ''), coalesce(r.resolution_notes, ''), coalesce(r.notes, ''), coalesce(r.created_by, ''), coalesce(r.created_at, ''), coalesce(r.updated_at, '')]::text[] as cells
from xpms.v_sheet_work_orders r;
comment on view xpms.v_playbook_work_orders is 'The Playbook Work Orders sheet exported from the database with every cell normalized, for the round-trip proof.';
