create view xpms.v_sheet_shipping_manifest with (security_invoker = true) as
with s0 as (select t.source_row, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 1) as record_id, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 3) as department, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 4) as category, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 5) as sub_category, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 6) as vendor_id, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 7) as item, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 8) as description, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 9) as container, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 10) as pallet_count, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 11) as piece_count, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 12) as length_ft, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 13) as width_ft, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 14) as height_ft, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 17) as weight, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 18) as shipment_date, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 19) as sender, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 20) as origin, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 21) as personnel_id, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 22) as location_id, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 23) as carrier, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 24) as carrier_phone, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 25) as trailer_license, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 26) as seal_number, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 27) as freight_type, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 28) as tracking_number, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 29) as bill_of_lading_bol, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 30) as status, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 31) as flag, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 32) as notes, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 33) as created_by, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 34) as created_at, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 35) as updated_at
from xpms.production_template_rows t
left join xpms.production_template_values v
  on v.template_code = t.template_code and v.sheet_name = t.sheet_name and v.source_row = t.source_row
where t.template_code = 'XOS-4.0' and t.sheet_name = 'Shipping Manifest'
group by t.source_row),
s1 as (select r.*, (xpms.pb_cover(7, 3)) as project_id from s0 r),
s2 as (select r.*, (round(xpms.pb_n(r.length_ft) * xpms.pb_n(r.width_ft) * xpms.pb_n(r.height_ft), 2)) as volume_cu_ft from s1 r),
s3 as (select r.*, (coalesce(r.length_ft, '') || ' ft x ' || coalesce(r.width_ft, '') || ' ft x ' || coalesce(r.height_ft, '') || ' ft') as dimensions from s2 r)
select * from s3;
