comment on column xpms.v_sheet_procurement_catalog.resource_kind is 'RESOURCE KIND (column D), field.';
comment on column xpms.v_sheet_procurement_catalog.schema_family_xyz is 'SCHEMA FAMILY (XYZ) (column E), field.';
comment on column xpms.v_sheet_procurement_catalog.default_gl_account is 'DEFAULT GL ACCOUNT (column F), field.';
comment on column xpms.v_sheet_procurement_catalog.default_gl_name is 'DEFAULT GL NAME (column G), field.';
comment on column xpms.v_sheet_procurement_catalog.default_cost_center is 'DEFAULT COST CENTER (column H), field.';
comment on column xpms.v_sheet_procurement_catalog.unit_of_measure is 'UNIT OF MEASURE (column I), field.';
comment on column xpms.v_sheet_procurement_catalog.grade_1_basic_low is 'GRADE 1 BASIC ($ LOW) (column J), field.';
comment on column xpms.v_sheet_procurement_catalog.grade_2_standard_cost is 'GRADE 2 STANDARD ($ COST) (column K), field.';
comment on column xpms.v_sheet_procurement_catalog.grade_3_premium_high is 'GRADE 3 PREMIUM ($ HIGH) (column L), field.';
comment on column xpms.v_sheet_procurement_catalog.description is 'DESCRIPTION (column M), field.';
comment on column xpms.v_sheet_procurement_catalog.specifications is 'SPECIFICATIONS (column N), field.';
comment on column xpms.v_sheet_procurement_catalog.lead_time_hrs is 'LEAD TIME (HRS) (column O), field.';
