create view xpms.v_sheet_staffing_requisition with (security_invoker = true) as
with s0 as (select t.source_row, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 1) as req_id, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 2) as event_phase, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 3) as role_code, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 6) as headcount, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 7) as duration_days, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 10) as status, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 11) as flag, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 12) as notes, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 13) as created_by, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 14) as created_at, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 15) as updated_at
from xpms.production_template_rows t
left join xpms.production_template_values v
  on v.template_code = t.template_code and v.sheet_name = t.sheet_name and v.source_row = t.source_row
where t.template_code = 'XOS-4.0' and t.sheet_name = 'Staffing Requisition'
group by t.source_row),
s1 as (select r.*, ((select x.rate_card_id from xpms.rate_card x where x.role_code = r.role_code order by x.source_row limit 1)) as rate_card_id from s0 r),
s2 as (select r.*, ((select x.job_title from xpms.role x where x.role_code = r.role_code)) as job_title from s1 r),
s3 as (select r.*, ((select x.standard_rate_minor / 100.0 from xpms.rate_card x where x.rate_card_id = r.rate_card_id)) as standard_rate from s2 r),
s4 as (select r.*, (xpms.pb_n(r.headcount) * xpms.pb_n(r.duration_days) * r.standard_rate) as total_estimated_cost from s3 r)
select * from s4;
