create view xpms.v_sheet_crew_shifts with (security_invoker = true) as
with s0 as (select t.source_row, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 1) as shift_id, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 2) as project_id, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 3) as shift_date, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 4) as department, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 5) as location_name, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 6) as personnel_id, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 8) as role_code, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 9) as rate_card_id, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 11) as scheduled_call_time, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 12) as scheduled_wrap_time, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 13) as scheduled_meal_break_hrs, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 19) as status, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 20) as flag, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 21) as notes, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 22) as created_by, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 23) as created_at, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 24) as updated_at
from xpms.production_template_rows t
left join xpms.production_template_values v
  on v.template_code = t.template_code and v.sheet_name = t.sheet_name and v.source_row = t.source_row
where t.template_code = 'XOS-4.0' and t.sheet_name = 'Crew Shifts'
group by t.source_row),
s1 as (select r.*, (nullif(btrim(coalesce((select p.first_name from xpms.v_sheet_personnel_roster p where p.personnel_id = r.personnel_id order by p.source_row limit 1), '') || ' ' || coalesce((select p.last_name from xpms.v_sheet_personnel_roster p where p.personnel_id = r.personnel_id order by p.source_row limit 1), '')), '')) as crew_name from s0 r),
s2 as (select r.*, ((select ro.job_title from xpms.rate_card rc join xpms.role ro on ro.role_code = rc.role_code where rc.rate_card_id = r.rate_card_id)) as job_title from s1 r),
s3 as (select r.*, (round(xpms.pb_hours(r.scheduled_call_time, r.scheduled_wrap_time) - xpms.pb_n(r.scheduled_meal_break_hrs), 2)) as net_scheduled_hours from s2 r),
s4 as (select r.*, (coalesce((select x.pay_basis from xpms.rate_card x where x.rate_card_id = r.rate_card_id), 'Day Rate')) as pay_basis from s3 r),
s5 as (select r.*, (coalesce((select x.standard_rate_minor / 100.0 from xpms.rate_card x where x.rate_card_id = r.rate_card_id), 0)) as standard_rate from s4 r),
s6 as (select r.*, (round(r.standard_rate / 10, 2)) as hourly_base_rate from s5 r),
s7 as (select r.*, (case when r.pay_basis = 'Day Rate' then r.standard_rate else round(r.hourly_base_rate * r.net_scheduled_hours, 2) end) as scheduled_pay from s6 r)
select * from s7;
