create view xpms.v_sheet_crew_timesheets with (security_invoker = true) as
with s0 as (select t.source_row, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 1) as timesheet_id, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 2) as project_id, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 3) as shift_id, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 10) as actual_in_time, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 11) as meal_out_time, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 12) as meal_in_time, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 13) as actual_out_time, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 29) as status, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 30) as flag, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 31) as notes, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 32) as created_by, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 33) as created_at, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 34) as updated_at
from xpms.production_template_rows t
left join xpms.production_template_values v
  on v.template_code = t.template_code and v.sheet_name = t.sheet_name and v.source_row = t.source_row
where t.template_code = 'XOS-4.0' and t.sheet_name = 'Crew Timesheets'
group by t.source_row),
s1 as (select r.*, ((select x.shift_date::date from xpms.v_sheet_crew_shifts x where x.source_row = r.source_row)) as work_date from s0 r),
s2 as (select r.*, ((select x.personnel_id from xpms.v_sheet_crew_shifts x where x.source_row = r.source_row)) as personnel_id from s1 r),
s3 as (select r.*, (nullif(btrim(coalesce((select p.first_name from xpms.v_sheet_personnel_roster p where p.personnel_id = r.personnel_id order by p.source_row limit 1), '') || ' ' || coalesce((select p.last_name from xpms.v_sheet_personnel_roster p where p.personnel_id = r.personnel_id order by p.source_row limit 1), '')), '')) as crew_name from s2 r),
s4 as (select r.*, ((select x.role_code from xpms.v_sheet_crew_shifts x where x.source_row = r.source_row)) as role_code from s3 r),
s5 as (select r.*, ((select x.rate_card_id from xpms.v_sheet_crew_shifts x where x.source_row = r.source_row)) as rate_card_id from s4 r),
s6 as (select r.*, ((select x.job_title from xpms.v_sheet_crew_shifts x where x.source_row = r.source_row)) as job_title from s5 r),
s7 as (select r.*, (round(xpms.pb_hours(r.meal_out_time, r.meal_in_time), 2)) as meal_duration_hrs from s6 r),
s8 as (select r.*, (round(xpms.pb_hours(r.actual_in_time, r.actual_out_time), 2)) as total_elapsed_hours from s7 r),
s9 as (select r.*, (round(r.total_elapsed_hours - r.meal_duration_hrs, 2)) as net_worked_hours from s8 r),
s10 as (select r.*, (round(least(8, r.net_worked_hours), 2)) as regular_hours_1_0x from s9 r),
s11 as (select r.*, (round(greatest(0, least(4, r.net_worked_hours - 8)), 2)) as overtime_hours_1_5x from s10 r),
s12 as (select r.*, (round(greatest(0, r.net_worked_hours - 12), 2)) as double_time_hours_2_0x from s11 r),
s13 as (select r.*, ((select x.hourly_base_rate from xpms.v_sheet_crew_shifts x where x.source_row = r.source_row)) as hourly_base_rate from s12 r),
s14 as (select r.*, (round(r.regular_hours_1_0x * r.hourly_base_rate, 2)) as regular_pay from s13 r),
s15 as (select r.*, (round(r.overtime_hours_1_5x * r.hourly_base_rate * 1.5, 2)) as overtime_pay from s14 r),
s16 as (select r.*, (round(r.double_time_hours_2_0x * r.hourly_base_rate * 2, 2)) as double_time_pay from s15 r),
s17 as (select r.*, (case when xpms.pb_hours(r.actual_in_time, r.meal_out_time) > 6 then 50 else 0 end) as meal_penalty_pay from s16 r),
s18 as (select r.*, (coalesce((select x.per_diem_rate_minor / 100.0 from xpms.rate_card x where x.rate_card_id = r.rate_card_id), 0)) as per_diem_pay from s17 r),
s19 as (select r.*, (round(r.regular_pay + r.overtime_pay + r.double_time_pay + r.meal_penalty_pay + r.per_diem_pay, 2)) as gross_earnings from s18 r),
s20 as (select r.*, ((select x.gl_account::numeric from xpms.rate_card_resolved x where x.rate_card_id = r.rate_card_id)) as expense_gl_account from s19 r),
s21 as (select r.*, ((select x.gl_account_name from xpms.rate_card_resolved x where x.rate_card_id = r.rate_card_id)) as expense_gl_name from s20 r)
select * from s21;
