create view xpms.v_sheet_purchase_orders with (security_invoker = true) as
with s0 as (select t.source_row, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 1) as po_number, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 2) as project_id, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 3) as vendor_id, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 5) as issue_date, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 6) as delivery_date, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 7) as payment_terms, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 9) as tax_amount, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 10) as shipping_amount, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 13) as invoiced_amount, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 14) as paid_amount, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 15) as currency, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 16) as status, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 17) as flag, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 18) as notes, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 19) as created_by, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 20) as created_at, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 21) as updated_at
from xpms.production_template_rows t
left join xpms.production_template_values v
  on v.template_code = t.template_code and v.sheet_name = t.sheet_name and v.source_row = t.source_row
where t.template_code = 'XOS-4.0' and t.sheet_name = 'Purchase Orders'
group by t.source_row),
s1 as (select r.*, ((select x.company from xpms.v_sheet_vendor_directory x where x.vendor_id = r.vendor_id order by x.source_row limit 1)) as vendor_name from s0 r),
s2 as (select r.*, (coalesce((select sum(x.total_amount) from xpms.v_sheet_po_line_items x where x.po_number = r.po_number), 0)) as subtotal_amount from s1 r),
s3 as (select r.*, (r.subtotal_amount + coalesce(xpms.pb_n(r.tax_amount), 0) + coalesce(xpms.pb_n(r.shipping_amount), 0)) as total_amount from s2 r),
s4 as (select r.*, (r.total_amount) as committed_amount from s3 r)
select * from s4;
comment on view xpms.v_sheet_purchase_orders is 'The Playbook Purchase Orders sheet as the database holds it: one row per source row, computed columns reproduced in SQL.';
