with s0 as (select t.source_row, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 1) as date, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 2) as account_code, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 3) as cost_center_code, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 5) as vendor_id, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 6) as item_id, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 7) as description, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 8) as quantity, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 9) as unit_basis, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 10) as amount, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 11) as tax_type, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 12) as currency, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 13) as external_ref, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 14) as line_state
