create view xpms.v_sheet_inspection_compliance with (security_invoker = true) as
with s0 as (select t.source_row, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 1) as record_id, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 4) as department, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 5) as category, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 6) as sub_category, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 7) as inspection_type, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 8) as agency, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 9) as ahj_jurisdiction_code, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 10) as permit_number, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 11) as permit_doc_id, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 12) as location_id, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 13) as vendor_id, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 14) as inspector_name, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 15) as scheduled_date, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 16) as completed_date, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 17) as result, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 18) as deficiency_summary, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 19) as sign_off_date, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 20) as sign_off_url, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 21) as status, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 22) as flag, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 23) as notes, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 24) as created_by, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 25) as created_at, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 26) as updated_at
from xpms.production_template_rows t
left join xpms.production_template_values v
  on v.template_code = t.template_code and v.sheet_name = t.sheet_name and v.source_row = t.source_row
