create view xpms.v_sheet_incident_cad_log with (security_invoker = true) as
with s0 as (select t.source_row, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 1) as record_id, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 2) as organization, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 3) as project_id, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 4) as department, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 5) as category, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 6) as sub_category, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 7) as incident_timestamp, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 8) as emergency_code_id, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 9) as severity_level, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 10) as location_id, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 11) as reported_by, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 12) as lead_responder_id, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 13) as dispatch_agency_unit, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 14) as dispatch_time, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 15) as on_scene_time, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 16) as cleared_time, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 17) as police_report_number, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 18) as incident_summary, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 19) as resolution_protocol, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 20) as follow_up_required, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 21) as status, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 22) as flag, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 23) as notes, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 24) as created_by, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 25) as created_at, max(xpms.pb_cell(v.value_text, v.value_kind)) filter (where v.column_ordinal = 26) as updated_at
from xpms.production_template_rows t
left join xpms.production_template_values v
  on v.template_code = t.template_code and v.sheet_name = t.sheet_name and v.source_row = t.source_row
where t.template_code = 'XOS-4.0' and t.sheet_name = 'Incident CAD Log'
group by t.source_row)
select * from s0;
