create view xpms.v_sheet_counterparty_types with (security_invoker = true) as
select d.source_row, xpms.pb_text(d.classification_code) as classification_code, xpms.pb_text(xpms.pb_overlay('Counterparty Types', d.source_row::integer, 'COUNTERPARTY TYPE', (d.counterparty_type)::text)) as counterparty_type, xpms.pb_text(d.vendor_class) as vendor_class, xpms.pb_text(d.clearance_tier) as clearance_tier, xpms.pb_text(xpms.pb_overlay('Counterparty Types', d.source_row::integer, 'COMPLIANCE REQUIREMENTS', (d.definition)::text)) as compliance_requirements, xpms.pb_text(d.default_account_code) as default_gl_account, xpms.pb_text(d.source_status) as status, xpms.pb_text(d.source_created_by) as created_by, xpms.pb_ts(d.source_created_at) as created_at, xpms.pb_ts(d.source_updated_at) as updated_at from xpms.dim_counterparty_type d where d.source_row is not null
union all
select i.source_row, xpms.pb_text(max(i.proposed_value) filter (where i.source_column = 'CLASSIFICATION CODE')) as c0, xpms.pb_text(max(i.proposed_value) filter (where i.source_column = 'COUNTERPARTY TYPE')) as c1, xpms.pb_text(max(i.proposed_value) filter (where i.source_column = 'VENDOR CLASS')) as c2, xpms.pb_text(max(i.proposed_value) filter (where i.source_column = 'CLEARANCE TIER')) as c3, xpms.pb_text(max(i.proposed_value) filter (where i.source_column = 'COMPLIANCE REQUIREMENTS')) as c4, xpms.pb_text(max(i.proposed_value) filter (where i.source_column = 'DEFAULT GL ACCOUNT')) as c5, xpms.pb_text(max(i.proposed_value) filter (where i.source_column = 'STATUS')) as c6, xpms.pb_text(max(i.proposed_value) filter (where i.source_column = 'CREATED BY')) as c7, xpms.pb_text(max(i.proposed_value) filter (where i.source_column = 'CREATED AT')) as c8, xpms.pb_text(max(i.proposed_value) filter (where i.source_column = 'UPDATED AT')) as c9 from xpms.intake i where i.source_file = 'XOS-4.0_Production-Playbook_2026.xlsx' and i.source_sheet = 'Counterparty Types' and i.reason like 'Row % is in the Playbook %' group by i.source_row;
