select r.source_row::integer as source_row, array[xpms.pb_text((r.record_id)::text), xpms.pb_text((r.organization)::text), xpms.pb_text((r.project)::text), xpms.pb_text((r.department)::text), xpms.pb_text((r.category)::text), xpms.pb_text((r.sub_category)::text), xpms.pb_text((r.verbiage)::text), xpms.pb_text((r.title)::text), xpms.pb_text((r.body)::text), xpms.pb_text((r.description)::text), xpms.pb_text((r.status)::text), xpms.pb_bool((r.flag)::boolean), xpms.pb_text((r.notes)::text), xpms.pb_text((r.created_by)::text), xpms.pb_ts((r.created_at)::timestamp), xpms.pb_ts((r.updated_at)::timestamp)]::text[] as cells
