create view xpms.v_sheet_enumerations with (security_invoker = true) as
with s0 as (select r.source_row, r.record_id, r.department, r.category, r.sub_category, r.enum_domain, r.enum_code, r.enum_label, r.description, r.sort_order, r.color_code, r.target_entity, r.is_default, r.status, r.flag, r.notes, r.created_by, r.created_at, r.updated_at from xpms.std_enumeration r),
s1 as (select r.*, (xpms.pb_cover(8, 9)) as organization from s0 r),
s2 as (select r.*, (xpms.pb_cover(7, 3)) as project from s1 r),
s3 as (select r.*, ((select u.v from (select distinct on (v) v, ord from (select e.enum_label::text as v, e.source_row as ord from xpms.std_enumeration e where e.enum_domain = 'Workflow Status' union all select x.v, 100000 + x.k from (values ('Planned', 1), ('Behind', 2), ('Milestone Met', 3)) as x(v, k)) a order by v, ord) u order by u.ord offset (r.source_row - 2) limit 1)) as workflow_status from s2 r),
s4 as (select r.*, ((select u.v from (select distinct on (v) v, ord from (select e.enum_label::text as v, e.source_row as ord from xpms.std_enumeration e where e.enum_domain = 'Incident Priority' union all select x.v, 100000 + x.k from (values ('Critical', 1), ('High', 2), ('Medium', 3), ('Low', 4)) as x(v, k)) a order by v, ord) u order by u.ord offset (r.source_row - 2) limit 1)) as incident_priority from s3 r),
s5 as (select r.*, ((select u.v from (select distinct on (v) v, ord from (select e.enum_label::text as v, e.source_row as ord from xpms.std_enumeration e where e.enum_domain in ('Workflow Status', 'Payment Status') union all select x.v, 100000 + x.k from (values ('Draft', 1), ('Published', 2), ('Confirmed', 3), ('Checked-In', 4), ('Rejected', 5), ('Exported', 6)) as x(v, k)) a order by v, ord) u order by u.ord offset (r.source_row - 2) limit 1)) as shift_and_timesheet_status from s4 r),
s6 as (select r.*, ((select u.v from (select distinct on (v) v, ord from (select e.enum_label::text as v, e.source_row as ord from xpms.std_enumeration e where e.enum_domain = 'Clearance Tier' union all select x.v, 100000 + x.k from (values ('Tier 1 All-Access', 1), ('Tier 2 Production', 2), ('Tier 3 Crew', 3), ('Tier 4 Guest', 4)) as x(v, k)) a order by v, ord) u order by u.ord offset (r.source_row - 2) limit 1)) as clearance_tier from s5 r),
s7 as (select r.*, ((select u.v from (select distinct on (v) v, ord from (select e.enum_label::text as v, e.source_row as ord from xpms.std_enumeration e where e.enum_domain in ('Order Type', 'Payment Status', 'Workflow Status') union all select x.v, 100000 + x.k from (values ('Quoted', 1), ('Committed', 2), ('Invoiced', 3), ('Draft', 4), ('Issued', 5), ('Acknowledged', 6), ('Received', 7), ('Closed', 8), ('Submitted', 9), ('Under Review', 10)) as x(v, k)) a order by v, ord) u order by u.ord offset (r.source_row - 2) limit 1)) as commercial_state from s6 r),
s8 as (select r.*, ((select u.v from (select distinct on (v) v, ord from (select e.enum_label::text as v, e.source_row as ord from xpms.std_enumeration e where e.enum_domain = 'Asset Condition' union all select x.v, 100000 + x.k from (values ('Poor', 1), ('Damaged', 2)) as x(v, k)) a order by v, ord) u order by u.ord offset (r.source_row - 2) limit 1)) as asset_condition from s7 r),
s9 as (select r.*, ((select u.v from (select distinct on (v) v, ord from (select e.enum_label::text as v, e.source_row as ord from xpms.std_enumeration e where e.enum_domain = 'Workflow Status' and e.target_entity in ('Asset Inventory', 'Shipping Manifest', 'Universal') union all select x.v, 100000 + x.k from (values ('In Warehouse', 1), ('Under Repair', 2), ('Decommissioned', 3)) as x(v, k)) a order by v, ord) u order by u.ord offset (r.source_row - 2) limit 1)) as deployment_state from s8 r)
select * from s9;
comment on view xpms.v_sheet_enumerations is 'The Playbook Enumerations sheet as the database holds it: one row per source row, computed columns reproduced in SQL.';
comment on column xpms.v_sheet_enumerations.source_row is 'Row number in the source sheet.';
comment on column xpms.v_sheet_enumerations.record_id is 'RECORD ID (column A), field.';
comment on column xpms.v_sheet_enumerations.organization is 'ORGANIZATION (column B), computed.';
comment on column xpms.v_sheet_enumerations.project is 'PROJECT (column C), computed.';
comment on column xpms.v_sheet_enumerations.department is 'DEPARTMENT (column D), field.';
comment on column xpms.v_sheet_enumerations.category is 'CATEGORY (column E), field.';
comment on column xpms.v_sheet_enumerations.sub_category is 'SUB CATEGORY (column F), field.';
comment on column xpms.v_sheet_enumerations.enum_domain is 'ENUM DOMAIN (column G), field.';
comment on column xpms.v_sheet_enumerations.enum_code is 'ENUM CODE (column H), field.';
comment on column xpms.v_sheet_enumerations.enum_label is 'ENUM LABEL (column I), field.';
comment on column xpms.v_sheet_enumerations.description is 'DESCRIPTION (column J), field.';
comment on column xpms.v_sheet_enumerations.sort_order is 'SORT ORDER (column K), field.';
comment on column xpms.v_sheet_enumerations.color_code is 'COLOR CODE (column L), field.';
comment on column xpms.v_sheet_enumerations.target_entity is 'TARGET ENTITY (column M), field.';
comment on column xpms.v_sheet_enumerations.is_default is 'IS DEFAULT (column N), field.';
comment on column xpms.v_sheet_enumerations.status is 'STATUS (column O), field.';
comment on column xpms.v_sheet_enumerations.workflow_status is 'Workflow Status (column P), computed.';
comment on column xpms.v_sheet_enumerations.incident_priority is 'Incident Priority (column Q), computed.';
comment on column xpms.v_sheet_enumerations.shift_and_timesheet_status is 'Shift & Timesheet Status (column R), computed.';
comment on column xpms.v_sheet_enumerations.clearance_tier is 'Clearance Tier (column S), computed.';
comment on column xpms.v_sheet_enumerations.commercial_state is 'Commercial State (column T), computed.';
comment on column xpms.v_sheet_enumerations.asset_condition is 'Asset Condition (column U), computed.';
comment on column xpms.v_sheet_enumerations.deployment_state is 'Deployment State (column V), computed.';
comment on column xpms.v_sheet_enumerations.flag is 'FLAG (column W), field.';
comment on column xpms.v_sheet_enumerations.notes is 'NOTES (column X), field.';
comment on column xpms.v_sheet_enumerations.created_by is 'CREATED BY (column Y), field.';
comment on column xpms.v_sheet_enumerations.created_at is 'CREATED AT (column Z), field.';
comment on column xpms.v_sheet_enumerations.updated_at is 'UPDATED AT (column AA), field.';

create view xpms.v_playbook_enumerations with (security_invoker = true) as
select r.source_row::integer as source_row, array[xpms.pb_text((r.record_id)::text), xpms.pb_text((r.organization)::text), xpms.pb_text((r.project)::text), xpms.pb_text((r.department)::text), xpms.pb_text((r.category)::text), xpms.pb_text((r.sub_category)::text), xpms.pb_text((r.enum_domain)::text), xpms.pb_text((r.enum_code)::text), xpms.pb_text((r.enum_label)::text), xpms.pb_text((r.description)::text), xpms.pb_num((r.sort_order)::numeric), xpms.pb_text((r.color_code)::text), xpms.pb_text((r.target_entity)::text), xpms.pb_bool((r.is_default)::boolean), xpms.pb_text((r.status)::text), xpms.pb_text((r.workflow_status)::text), xpms.pb_text((r.incident_priority)::text), xpms.pb_text((r.shift_and_timesheet_status)::text), xpms.pb_text((r.clearance_tier)::text), xpms.pb_text((r.commercial_state)::text), xpms.pb_text((r.asset_condition)::text), xpms.pb_text((r.deployment_state)::text), xpms.pb_bool((r.flag)::boolean), xpms.pb_text((r.notes)::text), xpms.pb_text((r.created_by)::text), xpms.pb_ts((r.created_at)::timestamp), xpms.pb_ts((r.updated_at)::timestamp)]::text[] as cells
from xpms.v_sheet_enumerations r;
comment on view xpms.v_playbook_enumerations is 'The Playbook Enumerations sheet exported from the database with every cell normalized, for the round-trip proof.';
comment on column xpms.v_playbook_enumerations.source_row is 'Row number in the source sheet.';
